 30	/**
 31	 * Starts a minimal test server that calls dispatchRoute() with the supplied
 32	 * route table. If no route matches, responds with HTTP 404. Listens on an
 33	 * ephemeral port (0) on loopback.
 34	 */
 35	function startDispatchServer(routes: Route[]): Promise<{ server: Server; baseUrl: string }> {
 36	  return new Promise((resolve, reject) => {
 37	    const server = createServer((req: IncomingMessage, res: ServerResponse) => {
 38	      const method = req.method?.toUpperCase() ?? 'GET';
 39	      const url = req.url ?? '/';
 40	
 41	      dispatchRoute(req, res, method, url, 0, routes).then((matched) => {
 42	        if (!matched) {
 43	          res.writeHead(404, { 'Content-Type': 'application/json' });
 44	          res.end(JSON.stringify({ error: { code: 'NOT_FOUND', message: 'no route matched' } }));
 45	        }
 46	      }).catch((err) => {
 47	        process.stderr.write(`[test-server] Unhandled: ${String(err)}\n`);
 48	        if (!res.headersSent) {
 49	          res.writeHead(500, { 'Content-Type': 'application/json' });
 50	          res.end(JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'error' } }));
 51	        }
 52	      });
 53	    });
 54	
 55	    server.listen(0, '127.0.0.1', () => {
 56	      const addr = server.address();
 57	      if (addr && typeof addr === 'object') {
 58	        resolve({ server, baseUrl: `http://127.0.0.1:${addr.port}` });
 59	      } else {
 60	        reject(new Error('Could not determine server port'));
 61	      }
 62	    });
 63	
 64	    server.on('error', reject);
 65	  });
 66	}
 67	
 68	function stopServer(server: Server): Promise<void> {
 69	  return new Promise((resolve, reject) => {
 70	    server.close((err) => (err ? reject(err) : resolve()));
 71	  });
 72	}
