274	
275	/**
276	 * A declarative body-parsing route entry for {@link buildRoutes} and
277	 * {@link dispatchRoute}.
278	 *
279	 * - `method` — HTTP method; must be one of `GET`, `POST`, `PUT`, `PATCH`, or
280	 *   `DELETE` (uppercase). This constraint is enforced at test time by
281	 *   `mcp-server/tests/gui/route-table.test.ts`.
282	 * - `path` — Exact string path or a RegExp with named capture groups.
283	 * - `handler` — Receives the parsed body (or `undefined` when `noBody` is
284	 *   set), any named capture groups extracted from the RegExp match, and the
285	 *   parsed query parameters from the request URL.
286	 * - `statusCode` — Response status code (default `200`). Use `204` for empty
287	 *   responses — the dispatcher writes the header and skips `sendJson()`.
288	 * - `noBody` — When `true`, skip `readJsonBody()`.
289	 */
290	export interface Route {
291	  method: string;
292	  path: string | RegExp;
293	  handler: (body: unknown, groups?: Record<string, string>, query?: URLSearchParams) => Promise<unknown>;
294	  statusCode?: number;
295	  noBody?: boolean;
296	}
297	
298	// ---------------------------------------------------------------------------
299	// Meta helpers
300	// ---------------------------------------------------------------------------
301	
302	/**
303	 * Guards against path-traversal attacks on URL parameters that are used as
304	 * filesystem path segments.
305	 *
306	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
307	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
308	 * callers receive the same status as a missing project — no information leak.
309	 *
310	 * @param segment - The raw URL parameter value to validate.
311	 */
312	function assertSafeSlug(segment: string): void {
313	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
314	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
315	  }
316	}
317	
318	/**
319	 * Reads the `.meta.json` for a namespaced project at
320	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
321	 *
322	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
323	 * when the field is absent or null.
324	 *
325	 * When the meta file exists but contains malformed JSON, the function still
326	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
327	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
328	 * to URL param '…'`) so operators can detect corrupt meta files during
329	 * troubleshooting. API callers always receive the fallback value in this case.
330	 *
331	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
332	 * indicating that the `{repo}/{slug}` combination is not a known project in
333	 * this ledger. This is the project-existence check for namespaced routes.
334	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
335	 * information-hiding: invalid-input and missing-project cases are
336	 * indistinguishable from the client side.
337	 *
338	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
339	 * before any filesystem access is attempted (defence-in-depth).
340	 */
341	export async function resolveRepoName(
342	  ledgerRoot: string,
343	  repoUrlParam: string,
344	  slugUrlParam: string,
345	): Promise<string> {
346	  assertSafeSlug(repoUrlParam);
347	  assertSafeSlug(slugUrlParam);
348	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
349	  let raw: string;
350	  try {
351	    raw = await readFile(metaPath, 'utf-8');
352	  } catch {
353	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
354	  }
355	  try {
356	    const meta = JSON.parse(raw) as { repository_name?: string | null };
357	    return meta.repository_name ?? repoUrlParam;
358	  } catch {
359	    // Malformed .meta.json — project directory exists, fall back to URL param.
360	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
361	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
362	    return repoUrlParam;
363	  }
364	}
